import{_ as i}from"./chunks/screenshot-placeholder.DKyzYp9t.js";import{_ as e,o as n,c as l,a2 as s}from"./chunks/framework.CCtxZRER.js";const c=JSON.parse('{"title":"Membaca Kode & Spesifikasi","description":"Mencocokkan kode, nama, dan ukuran pada label dengan barang fisik.","frontmatter":{"title":"Membaca Kode & Spesifikasi","description":"Mencocokkan kode, nama, dan ukuran pada label dengan barang fisik.","status":"draf","dasar":"materi presentasi Gudang Teknik (slide 11)","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Tutorial","tingkat":"Pemula","sumber":["ppt-gudang-teknik"],"kata_kunci":["tutorial","kode barang","spesifikasi","label","bearing","6205-2RS","identifikasi","cocokkan"]},"headers":[],"relativePath":"tutorial/membaca-kode-barang.md","filePath":"tutorial/membaca-kode-barang.md"}'),t={name:"tutorial/membaca-kode-barang.md"};function r(o,a,d,m,k,g){return n(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="membaca-kode-spesifikasi" tabindex="-1">Membaca Kode &amp; Spesifikasi <a class="header-anchor" href="#membaca-kode-spesifikasi" aria-label="Permalink to &quot;Membaca Kode &amp; Spesifikasi&quot;">​</a></h1><p class="lead">Di latihan ini kamu belajar membaca label barang dan memastikan barang fisik benar-benar sama dengan yang tertulis.</p><div class="tip custom-block"><p class="custom-block-title">Sebelum mulai</p><ul><li><strong>Setelah latihan ini, kamu bisa</strong> menguraikan kode, nama, dan spesifikasi pada label, lalu mencocokkannya dengan barang.</li><li><strong>Tingkat:</strong> Pemula, sekitar 20 menit.</li><li><strong>Baca dulu:</strong> <a href="/WareHouse/divisi/kode-barang">Kode Barang</a> dan <a href="/WareHouse/divisi/jenis-material">Jenis Material</a>.</li><li><strong>Siapkan:</strong> akses ke database barang (minta ke pembimbing), satu barang berlabel di gudang.</li></ul></div><h2 id="langkah" tabindex="-1">Langkah <a class="header-anchor" href="#langkah" aria-label="Permalink to &quot;Langkah&quot;">​</a></h2><ol><li><strong>Temukan label.</strong> Cari label pada rak atau kemasan barang. Jika label tidak ada, berhenti dan laporkan ke pembimbing.</li><li><strong>Baca kode barang.</strong> Contoh dari materi: <code>BRG-MEC-001</code>. Kode inilah yang dipakai di semua catatan.</li><li><strong>Baca nama dan tipe.</strong> Contoh: <em>Bearing 6205-2RS</em>. Nama menunjukkan jenis barang, sedangkan tipe membedakannya dari barang sejenis.</li><li><strong>Baca ukuran atau spesifikasi lain.</strong> Contoh: <em>25 × 52 × 15 mm</em>.</li><li><strong>Cocokkan dengan master material.</strong> Cari kode yang sama di master material. Pastikan nama, spesifikasi, satuan, dan lokasinya sama dengan label.</li><li><strong>Cocokkan dengan barang fisik.</strong> Periksa tulisan tipe pada barangnya. Pada bearing, tipe biasanya tercetak di sisi cincin luar.</li><li><strong>Catat temuan yang tidak cocok</strong>, misalnya label berbeda dengan tulisan di barang, lalu laporkan ke pembimbing.</li></ol><figure><p><img src="'+i+'" alt="Placeholder: foto contoh label barang di rak"></p><figcaption>Placeholder. Ganti dengan foto label barang di Gudang Teknik.</figcaption></figure><h2 id="latihan" tabindex="-1">Latihan <a class="header-anchor" href="#latihan" aria-label="Permalink to &quot;Latihan&quot;">​</a></h2><p>Uraikan label berikut:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BRG-MEC-001  –  Bearing 6205-2RS  –  25 × 52 × 15 mm</span></span></code></pre></div><ol><li>Kelompok material apa yang kemungkinan ditunjukkan oleh <code>MEC</code>?</li><li>Berapa diameter dalam bearing tersebut?</li><li>Apa arti akhiran <code>2RS</code>?</li></ol><details class="details custom-block"><summary>Lihat jawaban</summary><ol><li><em>Mechanical Parts</em>. Konfirmasi dengan aturan pengodean resmi gudang.</li><li>25 mm. Urutan ukurannya adalah diameter dalam × diameter luar × tebal.</li><li>Bearing memakai seal karet di kedua sisi.</li></ol></details><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Bacakan kode dengan suara saat mengambil barang. Cara sederhana ini mengurangi salah ambil.</li><li>Jika dua barang sangat mirip, bandingkan spesifikasinya berdampingan sebelum memilih.</li></ul><h2 id="kesalahan-umum" tabindex="-1">Kesalahan umum <a class="header-anchor" href="#kesalahan-umum" aria-label="Permalink to &quot;Kesalahan umum&quot;">​</a></h2><ul><li>Mencocokkan berdasarkan nama saja tanpa melihat tipe dan ukuran.</li><li>Menganggap label rak pasti benar, padahal barang bisa saja diletakkan di rak yang salah.</li></ul><h2 id="hasil-yang-diharapkan" tabindex="-1">Hasil yang diharapkan <a class="header-anchor" href="#hasil-yang-diharapkan" aria-label="Permalink to &quot;Hasil yang diharapkan&quot;">​</a></h2><p>Kamu bisa menjelaskan arti setiap bagian label dan menemukan setidaknya satu contoh barang yang kode, nama, dan spesifikasinya cocok di label, master material, dan barang fisik.</p>',17)])])}const p=e(t,[["render",r]]);export{c as __pageData,p as default};
